basesim.api:
OV.Soldiers = { generate(G,{baseId,rng?})→soldier (id set, not inserted; identical draws to Campaign.makeSoldier, newCampaign now uses it), applyMission(G,soldierId,{exp,hpLost,kills},rng)→{gains,promotedTo:int|null,woundDays} (OV.Morale.postMission then wound pct RNG(WOUND_RECOVERY_MIN,MAX); woundDays=ceil(hpLost·pct/100); wounded ⇒ leaves craft, template stays aboard as loose cargo), promotions(G)→[{id,from,to}] (top-down: commander from colonel if N≥PROMO_CMD_MIN, colonels N/15 from captains, captains N/8 from sergeants, sergeants N/4 from squaddies; highest promotionScore first, ties by G.soldiers order), daily(G) (woundDays−1 → soldierRecovered), kill(G,soldierId,cause,where?)→memorial entry|null, rename(G,soldierId,name)→{ok,reason?:'noSoldier'|'name'}, value(s)→20+missions+scoreBonus, promotionScore(s), quotas(n)→{sergeant,captain,colonel,commander}, woundDaysFor(hpLost,pct), RANK }

OV.Economy = { addScore(G,side 'xcom'|'alien'|'research',pts,lon|{lon,lat}?,lat?)→pts (region via GMath.regionAt, country via GMath.countryAt; throws on unknown side), ufoActivity30m(G), daily(G), upkeep(G)→{facilities,salaries,crafts,total} (completed facilities; salaries and craft rent include pending personnel/craft deliveries, orig), baseUpkeep(G,base), income(G) (Σ funding of non-pact countries), councilBonus(G,monthIdx?)→0|400, rating(G), ratingKey(G,rating?)→'rating.*', councilKey(G,rating)→'council.pleased'|'council.satisfied'|'council.dissatisfied', fundingChange(fundingK,capK,good,bad,rng)→{delta,mood} (Country::newMonth exact: RNG(5,20) always drawn, second RNG only in the up/down branch), monthEnd(G)→report (contract §5.7 shape + countries[{id,before,after,delta,mood,pact,newPact}]; newPact/alienBaseRevealed read from pactSigned / alienBaseFound(how 'agents') events with at===G.t; xcomTotal for country decisions = xcom+research+council bonus, orig), checkDefeat(G)→null|'council'|'debt'|'baseLost' }

OV.BaseSim = { capacities(G,baseId)→{personnel,labs,workshops,aliens,crafts:{cap,used}, storage:{cap,used(1 decimal),usedTenths}, radars:[{type,rangeNm,chance}], defences:[{type,power,hit}], hyper, upkeep} (personnel/crafts/storage count pending deliveries; storage counts all base crafts' equipment, orig), staff(G,baseId)→{soldiers,scientists:{total,free},engineers:{total,free}}, canPlace(G,baseId,type,x,y)→null|'unavailable'|'research'|'lift'|'cells'|'overlap'|'notConnected'|'funds' (must touch any existing facility, built or under construction), build→{ok,reason,facility}, canDismantle(G,baseId,x,y)→null|'empty'|'lift'|'notConnected'|'inUse', dismantle, canHire/hire(G,baseId,'soldier'|'scientist'|'engineer',n)→{ok,delivery}|reason 'count'|'quarters'|'funds'|'unavailable', sack(G,baseId,kind,nOrSoldierId) ('busy'|'away'|'noSoldier'|'count'), canBuy/buy(G,baseId,itemOrCraftType,n)→{ok,delivery} ('unavailable'|'hangar'|'storage'|'funds'|'count'), sell(G,baseId,itemId,n) ('stock'|'unsellable'), moveCargo(G,craftId,itemId,n) ('away'|'stock'|'inUse'|'unavailable'), setArmour(G,soldierId,armourId) ('unavailable'|'stock'|'away'), assignSoldier(G,soldierId,craftId|null) ('wounded'|'seats'|'away'|'base'|'noCraft'; leaving returns template items to stores, boarding backs the template from loose cargo then stores and drops what is missing), fitWeapon(G,craftId,slot,type|null) ('slot'|'away'|'stock'|'unavailable'; old launcher + floor(ammo/ammoPerItem) back to stores, new weapon ammo 0 ⇒ rearm), checkup(G,craftId)→status (repair→rearm→refuel→ready, no events; for World on arrival), renameBase(G,baseId,name), renameCraft(G,craftId,name), loose(G,craftId)→{itemId:n}, startResearch(G,baseId,topic,scientists)→{ok,project} ('busy'|'unavailable'|'scientists'|'labs'|'count'; consumes needItem / live alien; cost=max(1,floor(cost·geo.int(80,120)/100))), setScientists, cancelResearch (nothing refunded), researchLabel(G,baseId,topic)→'research.progress.*', completeResearch(G,baseId,topic)→researchDone event, startProduction(G,baseId,item,engineers,qty)→{ok,production} ('unavailable'|'engineers'|'workshops'|'hangar'|'count'; pays the first unit at once if it can), setEngineers, setQty ('count' if 0<qty≤done), cancelProduction (no refund), halfHourly(G), hourly(G), daily(G) }

OV.Dogfight = { create(G,craftId,ufoId)→dogfight|null (null if missing, already fighting, UFO not flying or MAX_DOGFIGHTS reached; a second dogfight on the same UFO shares escapeT/ufoReload), tick(G,id)→events[] ({t:'df.fire',from,slot?,weapon?}, {t:'df.hit',target,dmg,slot?}, {t:'df.miss',from,slot?}, {t:'df.move',dist}, {t:'df.retreat'}, {t:'df.breakOff'}, {t:'df.end',outcome}; calls finish when over), setMode(G,id,mode)→bool, toggleWeapon(G,id,slot)→bool, disengage(G,id), hitChance(G,id,slot)→int %, targetDist(G,id)→int, breakingOff(G,id)→bool, autoResolve(G,id,mode='standard',maxTicks=20000)→outcome, finish(G,id)→outcome (crashed/destroyed ⇒ OV.Missions.onUfoDown(G,ufoId,how,craftId) when the UFO is still flying; escaped ⇒ ufoEscaped; craftDestroyed ⇒ OV.World.loseCraft(G,craftId,'dogfight'); else craft returning to base at max speed; then dogfightEnd; minimal fallbacks only if those hooks are absent) }
